"""Texture recovery from noisy rings generated by independent spherical quadrature."""
from __future__ import annotations

import numpy as np
import pytest

from src.gimap.features.analyze.domain.crystal import fit_pole_figure, reflections
from src.gimap.features.analyze.domain.crystal import pole_models
from src.gimap.features.analyze.domain.crystal.texture import fit_crystal_orientation
from src.gimap.features.analyze.domain.crystal.texture_kernel import PoleLibrary, ring_families
from tools.benchmarks.crystal_orientation import (
    EXTERNAL, SEED, TEXTURES, _binned_density, expected_rings, public_frame, synthetic,
)


def test_kinematic_and_azimuthal_weights_agree_with_full_sphere_quadrature():
    phase, truth = expected_rings("MAPbI3_tetragonal")
    _, low, high, *_ = truth[0]
    families = ring_families(phase, reflections(phase, high), low, high)
    assert {f.label: f.multiplicity for f in families} == {"002": 2, "110": 4}
    axis = (2, 1, 2)
    library = PoleLibrary(phase, [axis], families, np.arange(90) + 0.5)
    width = 10.35
    for family, actual in zip(families, library.spline(np.log(width))[0]):
        normal = phase.cell.plane_normal(axis)
        psi = np.arccos(np.clip(abs(family.directions @ normal), 0., 1.))
        expected = sum(_binned_density(angle, width) * weight for angle, weight in zip(psi, family.fractions))
        # The production 12-midpoint bin integral is compared to 16-point Gauss quadrature.
        np.testing.assert_allclose(actual, np.radians(1.) * expected, atol=8e-6)
        assert actual.sum() == pytest.approx(1., abs=4e-5)


def test_narrow_tilted_poles_agree_with_direct_azimuthal_integral():
    phase, truth = expected_rings("MAPbI3_tetragonal")
    _, low, high, *_ = truth[0]
    families = ring_families(phase, reflections(phase, high), low, high)
    chi = np.arange(90) + 0.5
    axes = [(1, 1, 0), (1, 0, 0)]
    width = 2.35
    actual = PoleLibrary(phase, axes, families, chi).spline(np.log(width))
    for i, axis in enumerate(axes):
        direction = phase.cell.plane_normal(axis)
        for j, family in enumerate(families):
            cosine = np.clip(abs(family.directions @ direction), 0., 1.)
            expected = sum(weight * pole_models.binned(chi - 0.5, chi + 0.5, pole_models.GAUSSIAN_MOSAIC,
                                                       0., width, angle)
                           for angle, weight in zip(np.degrees(np.arccos(cosine)), family.fractions))
            np.testing.assert_allclose(actual[i, j], np.radians(1.) * expected, atol=5e-7)


@pytest.mark.parametrize("name", list(TEXTURES))
def test_joint_fit_recovers_crystallite_texture_with_poisson_noise_and_missing_angles(name):
    phase, rings = synthetic(name, SEED)
    axis, width, fraction, _ = TEXTURES[name]
    fit = fit_crystal_orientation(phase, rings)
    assert fit["axes"] == [list(axis)]
    assert abs(fit["fwhm_deg"] - width) < 3 * fit["fwhm_err_deg"]
    assert abs(fit["fraction_iso"] - fraction) < 3 * fit["fraction_iso_err"]
    assert fit["oriented_fraction"] == pytest.approx(1 - fit["fraction_iso"])
    assert fit["oriented_fraction_err"] == pytest.approx(fit["fraction_iso_err"])
    assert 0.6 < fit["reduced_chi2"] < 1.5
    assert fit["determined"]
    assert len(fit["rings"]) == len(rings)
    for record, observed in zip(fit["rings"], rings):
        profile = observed.profile
        assert not profile.measured[:5].any() and not profile.measured[-1]
        assert record["herman_measured"] == pytest.approx(profile.herman_measured())


def test_110_and_002_have_perpendicular_poles_in_one_mapbi3_texture():
    phase, rings = synthetic("MAPbI3_tetragonal", SEED)
    first = rings[0]
    fit = fit_crystal_orientation(phase, rings)
    record = fit["rings"][0]
    assert record["q"] == pytest.approx(0.998, abs=1e-3)
    families = {str(item["hkl"]): item for item in record["components"]}
    assert set(families) == {"110", "002"}
    chi = np.asarray(record["chi_deg"])
    # (002) is perpendicular to the (110) fibre. Of the four {110} poles, two lie
    # along the fibre and two perpendicular to it. Density, before the sin χ factor,
    # exposes both lobes. The axial term should only be present for {110}.
    pos = (chi > 0.) & (chi < 90.)
    sin_chi = np.sin(np.radians(chi[pos]))
    for family, low_to_middle in (("002", False), ("110", True)):
        density = np.asarray(families[family]["values"])[pos] / sin_chi
        low = np.argmin(np.abs(chi[pos] - 5.))
        middle = np.argmin(np.abs(chi[pos] - 45.))
        assert density[-1] > 1.5 * density[middle]
        assert (density[low] > 1.5 * density[middle]) == low_to_middle
    old = fit_pole_figure(first.profile, chi0_deg=None)
    assert old.chi2_red > 5
    assert record["reduced_chi2"] < 2
    assert abs(record["herman_measured"] - fit["herman_crystal"]) > 0.15


def test_reweighted_doublet_and_two_real_fibre_populations_are_selected_by_bic():
    phase, rings = synthetic("MAPbI3_tetragonal", SEED, second_axis=(0, 0, 1), share=0.42,
                             family_reweight=(((0, 0, 2), 0.15),))
    fit = fit_crystal_orientation(phase, rings)
    assert {tuple(axis) for axis in fit["axes"]} == {(1, 1, 0), (0, 0, 1)}
    assert fit["family_weights"] == "free"
    assert fit["parameters"] == 4 + sum(len(r["components"]) for r in fit["rings"])
    assert sum(p["fraction"] for p in fit["populations"]) + fit["fraction_iso"] == pytest.approx(1.)
    assert all(p["fraction_err"] > 0 and p["fwhm_err_deg"] > 0 for p in fit["populations"])
    weights = {row["hkl"]: row for row in fit["rings"][0]["components"]}
    assert weights["002"]["weight"] < 0.5 * weights["002"]["kinematic_weight"]
    assert fit["reduced_chi2"] < 2


def test_single_basal_pole_resolves_two_widths_of_the_same_plane():
    from src.gimap.features.analyze.domain.crystal import fold_profile
    from src.gimap.features.analyze.domain.crystal.texture import TextureRing

    phase, expected = expected_rings("PbI2")
    q, low, high, _, mask, background = expected[0]
    chi = np.arange(90) + 0.5
    sin_chi = np.sin(np.radians(chi))
    width, fraction = (8., 42.), (0.15, 0.50)
    density = sum(a * _binned_density(0., w) for a, w in zip(fraction, width))
    mean = 1500 * (density / sin_chi + 1. - sum(fraction)) + background
    rng = np.random.default_rng(104)
    observations = rng.poisson(mean, (2, len(chi))).astype(float)
    observations[:, ~mask] = np.nan
    values = observations.ravel()
    profile = fold_profile(np.r_[-chi, chi], values, np.sqrt(values), background)
    fit = fit_crystal_orientation(phase, [TextureRing(0, q, low, high, profile)])
    assert not fit["search_settings"]["noncollinear_poles_available"]
    assert fit["axes"] == [[0, 0, 1], [0, 0, 1]] and fit["determined"]
    assert fit["fwhm_deg"] is None
    assert fit["parameters"] == 5
    sharp, broad = sorted(fit["populations"], key=lambda p: p["fwhm_deg"])
    for actual, w, a in zip((sharp, broad), width, fraction):
        assert abs(actual["fwhm_deg"] - w) < 4 * actual["fwhm_err_deg"]
        assert abs(actual["fraction"] - a) < 4 * actual["fraction_err"]
    order = sum(p["fraction"] * pole_models.hermans(pole_models.GAUSSIAN_MOSAIC, 0., p["fwhm_deg"], 0.)
                for p in fit["populations"])
    assert fit["herman_crystal"] == pytest.approx(order)


@pytest.mark.skipif(not (EXTERNAL / "giwaxs_p08_mapi" / "S121_MAI_A2_00841.tif").exists(),
                    reason="The public P08 frame is unavailable.")
def test_public_p08_automatic_crystal_orientation_zero_roll():
    report = public_frame(sample_roll_deg=0.0)
    mapi, lead = report["crystal_orientation"]
    assert mapi["phase"] == "MAPbI3 (tetragonal)" and lead["phase"] == "PbI2"
    assert not mapi["determined"] and "joint or ring reduced χ² exceeds 5" in mapi["reasons"]
    assert len(mapi["populations"]) == 2 and mapi["fwhm_deg"] is None
    assert mapi["film_optics"]["electron_density_e_per_a3"] == pytest.approx(1.04228, abs=1e-5)
    assert mapi["film_optics"]["beta"] == pytest.approx(1.26942e-7, rel=1e-4)
    assert mapi["reduced_chi2"] == pytest.approx(33.07, abs=.15)
    assert [r["reduced_chi2"] for r in mapi["rings"]] == pytest.approx(
        [40.15, 13.26, 14.53, 59.36, 123.25, 8.94, 20.88, 8.44, 5.69, 2.95], abs=.25)
    strong = mapi["rings"][0]
    assert {r["hkl"] for r in strong["components"]} == {"110", "002"}
    assert strong["profile_settings"]["min_exit_deg"] == 0.
    assert strong["measured"][84] and strong["fit_mask"][84]
    assert strong["exit_transmission"][84] > 1.
    assert strong["observed"][84] < strong["fitted"][84] - 3*strong["sigma"][84]
    assert strong["largest_residual"]["chi_deg"] == pytest.approx(3.5)
    assert strong["largest_residual"]["observed_minus_fit_sigma"] > 20.
    for ring in mapi["rings"] + lead["rings"]:
        np.testing.assert_allclose(ring["fitted"], np.sum([r["values"] for r in ring["components"]], axis=0))
        assert len(ring["observed"]) == len(ring["measured"]) == len(ring["chi_deg"])
    assert lead["axes"] == [[0, 0, 1], [0, 0, 1]]
    assert not lead["search_settings"]["noncollinear_poles_available"]
    assert len(lead["rings"]) == 1
    assert lead["rings"][0]["reduced_chi2"] == pytest.approx(2.76, abs=.08)
    widths = sorted(p["fwhm_deg"] for p in lead["populations"])
    assert widths == pytest.approx([16.64, 65.37], abs=.3)


def test_transmitted_sharp_and_broad_populations_recover_their_own_widths_and_fractions():
    from tools.benchmarks.crystal_orientation import MIXTURE, MIXED_WIDTHS, SHARP_SHARE

    phase, rings = synthetic(MIXTURE, SEED)
    fit = fit_crystal_orientation(phase, rings)
    axis, _, iso, _ = TEXTURES["MAPbI3_tetragonal"]
    assert fit["axes"] == [list(axis)] * 2
    populations = sorted(fit["populations"], key=lambda p: p["fwhm_deg"])
    for pop, width, share in zip(populations, MIXED_WIDTHS, (SHARP_SHARE, 1.-SHARP_SHARE)):
        assert abs(pop["fwhm_deg"] - width) < 3 * pop["fwhm_err_deg"]
        assert abs(pop["fraction"] - (1.-iso)*share) < 3 * pop["fraction_err"]
    assert all(.6 < row["reduced_chi2"] < 1.5 for row in fit["rings"])
    assert any(np.max(r.transmission[r.profile.measured]) > 1.4 for r in rings)


@pytest.mark.skipif(not (EXTERNAL / "giwaxs_p08_mapi" / "S121_MAI_A2_00841.tif").exists(),
                    reason="The public P08 frame is unavailable.")
def test_public_p08_without_phases_keeps_the_existing_single_ring_results():
    report = public_frame(with_phases=False, sample_roll_deg=0.0)
    assert "crystal_orientation" not in report
    strong = report["rings"][0]
    assert strong["herman"] == pytest.approx(0.14187, abs=2e-4)
    pole = strong["pole_figure"]
    assert pole["model"] == "gaussian"
    assert pole["reduced_chi2"] == pytest.approx(31.1577, abs=0.06)
    assert "reduced χ² exceeds 5" in pole["quality_reasons"]


@pytest.mark.skipif(not (EXTERNAL / "giwaxs_p08_mapi" / "S121_MAI_A2_00841.tif").exists(),
                    reason="The public P08 frame is unavailable.")
def test_measured_roll_reaches_public_crystal_orientation():
    report = public_frame()
    measurement = report["sample_roll_measurement"]
    assert measurement["method"] == "combined" and measurement["significant"]
    assert measurement["origin"] == "automatic"
    assert report["geometry"]["sample_roll_deg"] == pytest.approx(measurement["deg"])
    assert measurement["deg"] == pytest.approx(-1.30, abs=.07)
    mapi, lead = report["crystal_orientation"]
    assert mapi["reduced_chi2"] == pytest.approx(22.45, abs=.25)
    assert not mapi["determined"] and lead["axes"] == [[0, 0, 1], [0, 0, 1]]
    assert lead["reduced_chi2"] == pytest.approx(2.08, abs=.12)
